<script setup lang="ts">
import {computed,ref} from 'vue';import TencentMap from './TencentMap.vue';import {capturePosition} from './geolocation';import {convertActionPoint,navigationTarget,navigationLinks,validActionPoint,emptyNavigationDestination,type CoordinateSystem} from '../../shared/place-actions';import type {StudioPlace} from './content-studio-api';
const props=withDefaults(defineProps<{place:StudioPlace;preview?:boolean;locale?:'zh'|'en'}>(),{preview:false,locale:'zh'}),pick=ref(false),message=ref(''),n=computed(()=>props.place.navigationDestination!),share=computed(()=>props.place.shareInfo!),target=computed(()=>navigationTarget(props.place,props.locale));
function enable(){n.value.coordinates=validActionPoint(props.place.coordinates)?{...props.place.coordinates,system:props.place.coordinates.system as CoordinateSystem}:{latitude:0,longitude:0,system:'WGS84'};}
function setPoint(p:{latitude:number;longitude:number}){n.value.coordinates=convertActionPoint({...p,system:'GCJ-02'},'WGS84');n.value.vehicleAccess='unknown';pick.value=false;}
async function locate(){try{const p=await capturePosition();n.value.coordinates={latitude:p.coords.latitude,longitude:p.coords.longitude,system:'WGS84'};n.value.vehicleAccess='unknown';}catch(e){message.value=(e as Error).message;}}
</script>
<template><section v-if="preview" class="navigation-preview"><h3>{{locale==='zh'?'导航目的地预览':'Directions preview'}}</h3><p v-if="target">{{target.name}} · {{target.explicit?(locale==='zh'?'独立导航目的地':'Separate destination'):(locale==='zh'?'地图位置，入口未确认':'Map location; entrance not confirmed')}}</p><p>{{n.notes[locale]}}</p><p>{{locale==='zh'?'车辆直达':'Vehicle access'}}：{{locale==='zh'?{yes:'已确认车辆可直达',no:'不适合车辆直达',unknown:'待核实'}[n.vehicleAccess]:{yes:'Vehicle access confirmed',no:'No vehicle access',unknown:'To be confirmed'}[n.vehicleAccess]}}</p><p>{{locale==='zh'?'草稿预览不生成公开分享链接':'Draft previews do not generate public share links.'}}</p><h4>{{locale==='zh'?'分享信息预览':'Share information preview'}}</h4><strong>{{share.title[locale]||place.name[locale]||place.name.zh}}</strong><p>{{share.description[locale]||place.summary[locale]}}</p><details v-if="target"><summary>{{locale==='zh'?'查看平台坐标和网页链接':'Platform coordinates and web links'}}</summary><p v-for="provider in (['amap','baidu','tencent','apple'] as const)"><a :href="navigationLinks(target,provider).web" target="_blank" rel="noopener noreferrer">{{provider}}</a> · {{navigationLinks(target,provider).point.system}} · {{navigationLinks(target,provider).point.latitude.toFixed(6)}}, {{navigationLinks(target,provider).point.longitude.toFixed(6)}}</p></details></section>
<details v-else><summary>导航目的地与分享</summary><p>地图标记位置与导航目的地分别维护。自然观察点、瀑布、徒步地点的中心点不等于停车场或入口；未确认车辆直达时不会默认提供驾车方案。</p><button v-if="!n.coordinates" type="button" @click="enable">设置独立导航坐标（从地图位置开始）</button><div v-if="n.coordinates" class="form-grid"><label>导航纬度<input aria-label="导航纬度" v-model.number="n.coordinates.latitude" @input="n.vehicleAccess='unknown'" type="number" step="any"><small v-if="!Number.isFinite(n.coordinates.latitude)||Math.abs(n.coordinates.latitude)>90" class="field-error">纬度必须在 -90 至 90 之间</small></label><label>导航经度<input aria-label="导航经度" v-model.number="n.coordinates.longitude" @input="n.vehicleAccess='unknown'" type="number" step="any"><small v-if="!Number.isFinite(n.coordinates.longitude)||Math.abs(n.coordinates.longitude)>180" class="field-error">经度必须在 -180 至 180 之间</small></label><label>导航坐标系<select aria-label="导航坐标系" v-model="n.coordinates.system" @change="n.vehicleAccess='unknown'"><option>WGS84</option><option>GCJ-02</option><option>BD-09</option></select></label></div><div class="field-actions"><button @click="pick=!pick">导航目的地点选</button><button @click="locate">导航目的地使用当前位置</button><button v-if="n.coordinates" @click="n.coordinates=null;n.vehicleAccess='unknown'">取消独立目的地</button></div><TencentMap v-if="pick" pick @pick="setPoint"/><p v-if="message" role="alert">{{message}}</p><div class="form-grid"><label>导航地点名称（中文）<input v-model="n.name.zh" placeholder="例如：已核实的停车场或入口名称"></label><label>Destination name（English，选填）<input v-model="n.name.en"></label><label class="wide">停车场或入口说明（中文）<textarea v-model="n.notes.zh"></textarea></label><label class="wide">Entrance / parking notes（English，选填）<textarea v-model="n.notes.en"></textarea></label><label>是否适合车辆直达<select aria-label="是否适合车辆直达" v-model="n.vehicleAccess"><option value="unknown">待核实</option><option value="yes" :disabled="!validActionPoint(n.coordinates)">已确认车辆可直达导航目的地</option><option value="no">不适合车辆直达</option></select></label><label>可选分享标题（中文）<input v-model="share.title.zh"></label><label>Share title（English，选填）<input v-model="share.title.en"></label><label class="wide">可选分享摘要（中文）<textarea v-model="share.description.zh"></textarea></label><label class="wide">Share description（English，选填）<textarea v-model="share.description.en"></textarea></label></div><p>留空时复用地点名称、简介和真实封面；无封面使用品牌默认图。新字段随原草稿、历史和 ZIP 备份保存，不改变地图展示坐标。</p></details></template>
